y-between gap-x-8 gap-y-5 pb-8"} data-anim={"fade-up"}><div className={"flex flex-wrap items-center gap-3"}><a href={"#page=demo-law-firm-1-lawyer"} className={"custom-person transition-colors hover:bg-(--custom-tint)"}><img src={"https://draftmango.com/framo/assets/media/placeholder/1080x1440.svg"} alt={""} width={"80"} height={"80"} className={"size-10 rounded-full object-cover object-[50%_20%]"} /><span className={"grid text-[0.9375rem] font-medium leading-tight"}>{"Catherine Hale"}<small className={"text-[0.8125rem] font-normal text-(--custom-meta)"}>{"Chair, Corporate & M&A"}</small></span></a><a href={"#page=demo-law-firm-1-lawyer"} className={"custom-person transition-colors hover:bg-(--custom-tint)"}><img src={"https://draftmango.com/framo/assets/media/placeholder/1080x1440.svg"} alt={""} width={"80"} height={"80"} className={"size-10 rounded-full object-cover object-[50%_20%]"} /><span className={"grid text-[0.9375rem] font-medium leading-tight"}>{"Daniel Price"}<small className={"text-[0.8125rem] font-normal text-(--custom-meta)"}>{"Partner, Corporate & M&A"}</small></span></a></div><p className={"m-0 text-[0.9375rem] text-(--custom-meta)"}>{"6 min read"}</p></div><figure className={"m-0"} data-anim={"fade-up"}><img src={"https://draftmango.com/framo/assets/media/placeholder/2400x1350.svg"} alt={"A fountain pen resting on a marked-up draft agreement beside a cup of coffee"} width={"800"} height={"600"} className={"w-full aspect-[4/3] md:aspect-[21/9] object-cover rounded-sm"} fetchPriority={"high"} /><figcaption className={"mt-3.5 text-[0.9375rem] text-(--custom-meta)"}>{"The new form asks for deal documents most buyers have never had to file."}</figcaption></figure><div className={"grid grid-cols-1 lg:grid-cols-[minmax(0,46rem)_minmax(0,20rem)] justify-between gap-x-16 gap-y-12 mt-14 lg:mt-18"}><aside className={"lg:col-start-2 lg:row-start-1 lg:sticky lg:top-32 self-start custom-creds"} aria-labelledby={"lf-ar-points"} data-anim={"fade-up"}><div><h2 id={