import Page11 from './pages/Page11.jsx';
const pages={"demo-law-firm-1":Page0,"demo-law-firm-1-about":Page1,"demo-law-firm-1-article":Page2,"demo-law-firm-1-careers":Page3,"demo-law-firm-1-contact":Page4,"demo-law-firm-1-industries":Page5,"demo-law-firm-1-insights":Page6,"demo-law-firm-1-lawyer":Page7,"demo-law-firm-1-people":Page8,"demo-law-firm-1-practice":Page9,"demo-law-firm-1-practices":Page10,"demo-law-firm-1-pro-bono":Page11};
export default function App(){
const [page,setPage]=useState(()=>new URLSearchParams(location.hash.slice(1)).get('page')||"demo-law-firm-1");
useEffect(()=>{const change=()=>setPage(new URLSearchParams(location.hash.slice(1)).get('page')||"demo-law-firm-1");const navigate=e=>{const a=e.target.closest('a[href]');const href=a?.getAttribute('href');if(!href?.startsWith('#page='))return;const next=new URLSearchParams(href.slice(1)).get('page');if(!pages[next])return;e.preventDefault();e.stopPropagation();setPage(next);try{if(location.protocol!=='about:')history.pushState(null,'',href)}catch{}};document.addEventListener('click',navigate,true);window.addEventListener('hashchange',change);window.addEventListener('popstate',change);return()=>{document.removeEventListener('click',navigate,true);window.removeEventListener('hashchange',change);window.removeEventListener('popstate',change)}},[]);
useTemplateRuntime(page);const Page=pages[page]||Page0;return <div id='template-page' key={page}><Page/></div>;
